#!/usr/bin/env bash
# Run the NexusSim Postman collection headless with Newman.
#
# Usage:  bash postman/run_postman_tests.sh
# Requires: all services running (run_full_system.bat) and Node.js (npx).
#
# The gateway serves HTTPS with a local self-signed cert, hence --insecure.
# The collection is generated by postman/generate_collection.py.

set -euo pipefail

cd "$(dirname "$0")/.."

npx --yes newman run \
  postman/NexusSim_API_Collection.json \
  -e postman/NexusSim_Environment.json \
  --insecure \
  --reporters cli,htmlextra \
  --reporter-htmlextra-export postman/results/newman-report.html
